class User {
    constructor(id, firstName, lastName, email, password, gender, picture) {
        this._id = id;
        this._firstName = firstName;
        this._lastName = lastName;
        this._email = email;
        this._password = password;
        this._gender = gender;
        this._picture = picture;
    }

    // Getters
    get id() {
        return this._id;
    }

    get firstName() {
        return this._firstName;
    }

    get lastName() {
        return this._lastName;
    }

    get email() {
        return this._email;
    }

    get password() {
        return this._password;
    }

    get gender() {
        return this._gender;
    }

    get picture() {
        return this._picture;
    }

    // Setters
    set id(value) {
        this._id = value;
    }
    
    set firstName(value) {
        this._firstName = value;
    }

    set lastName(value) {
        this._lastName = value;
    }

    set email(value) {
        this._email = value;
    }

    set password(value) {
        this._password = value;
    }

    set gender(value) {
        this._gender = value;
    }

    set picture(value) {
        this._picture = value;
    }
}
